#!/usr/bin/env node
/**
 * Background render support for the APK.
 *
 * A WebView cannot promise anything once Android decides the app is idle. The
 * one thing that keeps a process alive and visible is a foreground service, so
 * this script writes a small one — plus the Capacitor plugin that starts it and
 * listens for the notification's STOP button.
 *
 * The android/ folder is generated by `npx cap add android` in CI and never
 * committed, so the Java lives here, in source, and is copied in during the
 * build. Everything is asserted afterwards: no exported component besides
 * MainActivity, and the service is dataSync-only.
 */
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const root = process.cwd();
const androidDir = join(root, 'android');
const javaDir = join(androidDir, 'app', 'src', 'main', 'java');
const manifestPath = join(androidDir, 'app', 'src', 'main', 'AndroidManifest.xml');

if (!existsSync(manifestPath)) {
  console.error('android-background: android/ not generated yet — run `npx cap add android` first.');
  process.exit(1);
}

function appId() {
  const candidates = [
    join(root, 'capacitor.config.json'),
    join(root, 'capacitor.config.ts'),
  ];
  for (const path of candidates) {
    if (!existsSync(path)) continue;
    const text = readFileSync(path, 'utf8');
    const m = text.match(/appId\s*:\s*['"]([^'"]+)['"]/);
    if (m) return m[1];
  }
  throw new Error('android-background: cannot find appId in capacitor config');
}

const id = appId();
const pkgDir = join(javaDir, ...id.split('.'));
await mkdir(pkgDir, { recursive: true });

const SERVICE = `package ${id};

import android.app.Notification;
import android.app.NotificationChannel;
import android.app.NotificationManager;
import android.app.PendingIntent;
import android.app.Service;
import android.content.Intent;
import android.os.Build;
import android.os.IBinder;
import androidx.annotation.Nullable;

/**
 * Keeps the render alive while the app is in the background.
 *
 * It does no DSP of its own: the webview's worker keeps working, this service
 * just stops Android from freezing or killing the process, and gives the owner a
 * progress line with a STOP button that works from the lock screen.
 */
public class AegisRenderService extends Service {
  public static final String CHANNEL_ID = "aegis_render";
  public static final String ACTION_START = "${id}.RENDER_START";
  public static final String ACTION_STOP = "${id}.RENDER_STOP";
  public static final String EXTRA_TEXT = "text";
  public static final String EXTRA_PCT = "pct";
  public static final int NOTIFICATION_ID = 4711;

  /** True while a render is protected by this service. */
  public static volatile boolean running = false;

  @Override
  public int onStartCommand(Intent intent, int flags, int startId) {
    if (intent != null && ACTION_STOP.equals(intent.getAction())) {
      sendBroadcast(new Intent(ACTION_STOP).setPackage(getPackageName()));
      return START_NOT_STICKY;
    }
    String text = intent != null ? intent.getStringExtra(EXTRA_TEXT) : null;
    int pct = intent != null ? intent.getIntExtra(EXTRA_PCT, 0) : 0;
    startForeground(NOTIFICATION_ID, build(text == null ? "Merender audio…" : text, pct));
    running = true;
    return START_NOT_STICKY;
  }

  private Notification build(String text, int pct) {
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
      NotificationManager nm = getSystemService(NotificationManager.class);
      if (nm != null && nm.getNotificationChannel(CHANNEL_ID) == null) {
        NotificationChannel channel = new NotificationChannel(
          CHANNEL_ID, "Render audio", NotificationManager.IMPORTANCE_LOW);
        channel.setDescription("Progres render di latar belakang");
        channel.setSound(null, null);
        nm.createNotificationChannel(channel);
      }
    }

    Intent open = new Intent(this, MainActivity.class);
    open.setFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_CLEAR_TOP);
    PendingIntent openPending = PendingIntent.getActivity(
      this, 0, open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);

    Intent stop = new Intent(this, AegisRenderService.class).setAction(ACTION_STOP);
    PendingIntent stopPending = PendingIntent.getService(
      this, 1, stop, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);

    Notification.Builder builder = Build.VERSION.SDK_INT >= Build.VERSION_CODES.O
      ? new Notification.Builder(this, CHANNEL_ID)
      : new Notification.Builder(this);

    return builder
      .setContentTitle("Aegis Sound Lab")
      .setContentText(text)
      .setSmallIcon(android.R.drawable.stat_sys_download)
      .setOngoing(true)
      .setOnlyAlertOnce(true)
      .setProgress(100, Math.max(0, Math.min(100, pct)), false)
      .setContentIntent(openPending)
      .addAction(new Notification.Action.Builder(null, "STOP", stopPending).build())
      .build();
  }

  @Nullable
  @Override
  public IBinder onBind(Intent intent) {
    return null;
  }

  @Override
  public void onDestroy() {
    running = false;
    super.onDestroy();
  }
}
`;

const PLUGIN = `package ${id};

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;
import android.content.IntentFilter;
import android.os.Build;
import androidx.core.content.ContextCompat;
import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;

/**
 * JS door to AegisRenderService.
 *
 * start()  — protect the process with a foreground service
 * update() — refresh the notification text and progress
 * stop()   — drop the service (render finished or cancelled)
 *
 * When the owner taps STOP in the notification, this plugin emits
 * "stopRequested" so the webview can cancel the actual render job.
 */
@CapacitorPlugin(name = "AegisRender")
public class AegisRenderPlugin extends Plugin {
  private BroadcastReceiver stopReceiver;

  @Override
  public void load() {
    stopReceiver = new BroadcastReceiver() {
      @Override
      public void onReceive(Context context, Intent intent) {
        JSObject payload = new JSObject();
        payload.put("source", "notification");
        notifyListeners("stopRequested", payload);
      }
    };
    IntentFilter filter = new IntentFilter(AegisRenderService.ACTION_STOP);
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
      getContext().registerReceiver(stopReceiver, filter, Context.RECEIVER_NOT_EXPORTED);
    } else {
      getContext().registerReceiver(stopReceiver, filter);
    }
  }

  @Override
  protected void handleOnDestroy() {
    if (stopReceiver != null) {
      try {
        getContext().unregisterReceiver(stopReceiver);
      } catch (IllegalArgumentException ignored) {
        // already gone
      }
      stopReceiver = null;
    }
    super.handleOnDestroy();
  }

  @PluginMethod
  public void start(PluginCall call) {
    String text = call.getString("text", "Merender audio…");
    int pct = call.getInt("progress", 0);
    Intent intent = new Intent(getContext(), AegisRenderService.class);
    intent.setAction(AegisRenderService.ACTION_START);
    intent.putExtra(AegisRenderService.EXTRA_TEXT, text);
    intent.putExtra(AegisRenderService.EXTRA_PCT, pct);
    ContextCompat.startForegroundService(getContext(), intent);
    JSObject ret = new JSObject();
    ret.put("running", true);
    call.resolve(ret);
  }

  @PluginMethod
  public void update(PluginCall call) {
    String text = call.getString("text", "Merender audio…");
    int pct = call.getInt("progress", 0);
    Intent intent = new Intent(getContext(), AegisRenderService.class);
    intent.setAction(AegisRenderService.ACTION_START);
    intent.putExtra(AegisRenderService.EXTRA_TEXT, text);
    intent.putExtra(AegisRenderService.EXTRA_PCT, pct);
    ContextCompat.startForegroundService(getContext(), intent);
    call.resolve();
  }

  @PluginMethod
  public void stop(PluginCall call) {
    getContext().stopService(new Intent(getContext(), AegisRenderService.class));
    call.resolve();
  }
}
`;

await writeFile(join(pkgDir, 'AegisRenderService.java'), SERVICE);
await writeFile(join(pkgDir, 'AegisRenderPlugin.java'), PLUGIN);

// MainActivity: register the plugin before the bridge is created.
const mainPath = join(pkgDir, 'MainActivity.java');
let main = await readFile(mainPath, 'utf8');
if (!main.includes('AegisRenderPlugin')) {
  if (main.includes('public class MainActivity extends BridgeActivity {')) {
    main = main.replace(
      'public class MainActivity extends BridgeActivity {',
      `public class MainActivity extends BridgeActivity {
  @Override
  public void onCreate(android.os.Bundle savedInstanceState) {
    // Must happen before super.onCreate: the bridge builds its plugin list then.
    registerPlugin(AegisRenderPlugin.class);
    super.onCreate(savedInstanceState);
  }
`,
    );
  } else {
    throw new Error('android-background: MainActivity has an unexpected shape');
  }
}
await writeFile(mainPath, main);

// Manifest: permissions + the service itself.
let manifest = await readFile(manifestPath, 'utf8');
const permissions = [
  'android.permission.FOREGROUND_SERVICE',
  'android.permission.FOREGROUND_SERVICE_DATA_SYNC',
  'android.permission.POST_NOTIFICATIONS',
];
for (const permission of permissions) {
  if (manifest.includes(permission)) continue;
  manifest = manifest.replace(
    /<uses-permission\b[^>]*\/>/,
    (first) => `${first}\n    <uses-permission android:name="${permission}" />`,
  );
}
if (!manifest.includes('AegisRenderService')) {
  manifest = manifest.replace(
    /<\/application>/,
    `        <service
            android:name=".AegisRenderService"
            android:exported="false"
            android:foregroundServiceType="dataSync" />
    </application>`,
  );
}
await writeFile(manifestPath, manifest);

// Assertions: the service must exist, be unexported, and dataSync-typed.
const check = await readFile(manifestPath, 'utf8');
for (const needle of [
  'AegisRenderService',
  'android:exported="false"\n            android:foregroundServiceType="dataSync"',
  'android.permission.FOREGROUND_SERVICE_DATA_SYNC',
]) {
  if (!check.includes(needle)) {
    console.error(`android-background: manifest is missing ${needle}`);
    process.exit(1);
  }
}

console.log(`android-background: service + plugin written for ${id}`);
